import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Mail, User, Phone, Lock, Eye, EyeOff, CheckCircle } from 'lucide-react';

const Register = ({ onRegister }) => {
  const navigate = useNavigate();
  const [formData, setFormData] = useState({
    firstName: '',
    lastName: '',
    email: '',
    phone: '',
    password: '',
    confirmPassword: '',
    acceptTerms: false,
  });

  const [errors, setErrors] = useState({});
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);
  const [success, setSuccess] = useState(false);

  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: type === 'checkbox' ? checked : value
    }));

    if (errors[name]) {
      setErrors(prev => ({ ...prev, [name]: '' }));
    }
  };

  const validateForm = () => {
    const newErrors = {};

    if (!formData.firstName.trim()) {
      newErrors.firstName = 'Le prénom est requis';
    }

    if (!formData.lastName.trim()) {
      newErrors.lastName = 'Le nom est requis';
    }

    if (!formData.email.trim()) {
      newErrors.email = "L'email est requis";
    } else if (!/\S+@\S+\.\S+/.test(formData.email)) {
      newErrors.email = "L'email est invalide";
    }

    if (formData.phone && !/^[+]?[\d\s-]{10,}$/.test(formData.phone)) {
      newErrors.phone = 'Le numéro de téléphone est invalide';
    }

    if (!formData.password) {
      newErrors.password = 'Le mot de passe est requis';
    } else if (formData.password.length < 8) {
      newErrors.password = 'Le mot de passe doit contenir au moins 8 caractères';
    }

    if (!formData.confirmPassword) {
      newErrors.confirmPassword = 'Veuillez confirmer le mot de passe';
    } else if (formData.password !== formData.confirmPassword) {
      newErrors.confirmPassword = 'Les mots de passe ne correspondent pas';
    }

    if (!formData.acceptTerms) {
      newErrors.acceptTerms = 'Vous devez accepter les conditions';
    }

    return newErrors;
  };

  const getPasswordStrength = () => {
    if (!formData.password) return { score: 0, label: '', color: '' };

    let score = 0;
    if (formData.password.length >= 8) score++;
    if (/[A-Z]/.test(formData.password)) score++;
    if (/[0-9]/.test(formData.password)) score++;
    if (/[^A-Za-z0-9]/.test(formData.password)) score++;

    const strengths = [
      { label: 'Très faible', color: 'bg-red-500' },
      { label: 'Faible', color: 'bg-orange-500' },
      { label: 'Moyen', color: 'bg-yellow-500' },
      { label: 'Fort', color: 'bg-green-500' },
      { label: 'Très fort', color: 'bg-emerald-600' },
    ];

    return strengths[Math.min(score, strengths.length - 1)];
  };

  const passwordStrength = getPasswordStrength();

  const handleSubmit = async (e) => {
    e.preventDefault();

    const validationErrors = validateForm();
    if (Object.keys(validationErrors).length > 0) {
      setErrors(validationErrors);
      return;
    }

    setIsSubmitting(true);

    // Simulation d'API
    setTimeout(() => {
      console.log('Inscription réussie:', formData);

      // Sauvegarder les données
      localStorage.setItem('isAuthenticated', 'true');
      localStorage.setItem('userEmail', formData.email);

      setIsSubmitting(false);
      setSuccess(true);

      // Appeler le callback d'inscription
      onRegister();

      // Rediriger
      setTimeout(() => {
        navigate('/dashboard');
      }, 2000);
    }, 1500);
  };

  if (success) {
    return (
      <AuthLayout 
        title="Inscription réussie !"
        subtitle="Votre compte a été créé avec succès."
        type="register"
      >
        <div className="text-center py-12">
          <div className="inline-flex p-4 rounded-full bg-green-100 dark:bg-green-900/30 mb-6">
            <CheckCircle size={48} className="text-green-600 dark:text-green-400" />
          </div>
          <h3 className="text-2xl font-bold text-neutral-900 dark:text-white mb-4">
            Félicitations !
          </h3>
          <p className="text-neutral-600 dark:text-neutral-400 mb-8">
            Votre compte a été créé avec succès. Vous allez être redirigé vers le tableau de bord.
          </p>
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary-600 mx-auto"></div>
        </div>
      </AuthLayout>
    );
  }

  return (
    <AuthLayout
      title="Créez votre compte"
      subtitle="Rejoignez-nous dès aujourd'hui pour commencer votre expérience."
      type="register"
    >
      <form onSubmit={handleSubmit} className="space-y-6">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {/* First Name */}
          <div>
            <label className="block text-sm font-medium text-neutral-700 dark:text-neutral-300 mb-2">
              Prénom <span className="text-red-500">*</span>
            </label>
            <div className="relative">
              <User className="absolute left-3 top-1/2 transform -translate-y-1/2 text-neutral-400" size={20} />
              <input
                type="text"
                name="firstName"
                value={formData.firstName}
                onChange={handleChange}
                placeholder="Votre prénom"
                className={`
                  w-full pl-11 pr-4 py-3.5 rounded-lg border
                  ${errors.firstName 
                    ? 'border-red-300 dark:border-red-700 bg-red-50 dark:bg-red-900/20' 
                    : 'border-neutral-300 dark:border-neutral-700 bg-white dark:bg-neutral-800'
                  }
                  text-neutral-900 dark:text-white
                  placeholder-neutral-500 dark:placeholder-neutral-400
                  focus:outline-none focus:ring-2 focus:ring-primary-500/50
                  transition-all duration-200
                `}
              />
            </div>
            {errors.firstName && (
              <p className="mt-2 text-sm text-red-600 dark:text-red-400">
                {errors.firstName}
              </p>
            )}
          </div>

          {/* Last Name */}
          <div>
            <label className="block text-sm font-medium text-neutral-700 dark:text-neutral-300 mb-2">
              Nom <span className="text-red-500">*</span>
            </label>
            <div className="relative">
              <User className="absolute left-3 top-1/2 transform -translate-y-1/2 text-neutral-400" size={20} />
              <input
                type="text"
                name="lastName"
                value={formData.lastName}
                onChange={handleChange}
                placeholder="Votre nom"
                className={`
                  w-full pl-11 pr-4 py-3.5 rounded-lg border
                  ${errors.lastName 
                    ? 'border-red-300 dark:border-red-700 bg-red-50 dark:bg-red-900/20' 
                    : 'border-neutral-300 dark:border-neutral-700 bg-white dark:bg-neutral-800'
                  }
                  text-neutral-900 dark:text-white
                  placeholder-neutral-500 dark:placeholder-neutral-400
                  focus:outline-none focus:ring-2 focus:ring-primary-500/50
                  transition-all duration-200
                `}
              />
            </div>
            {errors.lastName && (
              <p className="mt-2 text-sm text-red-600 dark:text-red-400">
                {errors.lastName}
              </p>
            )}
          </div>
        </div>

        {/* Email */}
        <div>
          <label className="block text-sm font-medium text-neutral-700 dark:text-neutral-300 mb-2">
            Adresse email <span className="text-red-500">*</span>
          </label>
          <div className="relative">
            <Mail className="absolute left-3 top-1/2 transform -translate-y-1/2 text-neutral-400" size={20} />
            <input
              type="email"
              name="email"
              value={formData.email}
              onChange={handleChange}
              placeholder="vous@exemple.com"
              className={`
                w-full pl-11 pr-4 py-3.5 rounded-lg border
                ${errors.email 
                  ? 'border-red-300 dark:border-red-700 bg-red-50 dark:bg-red-900/20' 
                  : 'border-neutral-300 dark:border-neutral-700 bg-white dark:bg-neutral-800'
                }
                text-neutral-900 dark:text-white
                placeholder-neutral-500 dark:placeholder-neutral-400
                focus:outline-none focus:ring-2 focus:ring-primary-500/50
                transition-all duration-200
              `}
            />
          </div>
          {errors.email && (
            <p className="mt-2 text-sm text-red-600 dark:text-red-400">
              {errors.email}
            </p>
          )}
        </div>

        {/* Phone */}
        <div>
          <label className="block text-sm font-medium text-neutral-700 dark:text-neutral-300 mb-2">
            Téléphone (optionnel)
          </label>
          <div className="relative">
            <Phone className="absolute left-3 top-1/2 transform -translate-y-1/2 text-neutral-400" size={20} />
            <input
              type="tel"
              name="phone"
              value={formData.phone}
              onChange={handleChange}
              placeholder="+33 1 23 45 67 89"
              className={`
                w-full pl-11 pr-4 py-3.5 rounded-lg border
                ${errors.phone 
                  ? 'border-red-300 dark:border-red-700 bg-red-50 dark:bg-red-900/20' 
                  : 'border-neutral-300 dark:border-neutral-700 bg-white dark:bg-neutral-800'
                }
                text-neutral-900 dark:text-white
                placeholder-neutral-500 dark:placeholder-neutral-400
                focus:outline-none focus:ring-2 focus:ring-primary-500/50
                transition-all duration-200
              `}
            />
          </div>
          {errors.phone && (
            <p className="mt-2 text-sm text-red-600 dark:text-red-400">
              {errors.phone}
            </p>
          )}
        </div>

        {/* Password */}
        <div>
          <label className="block text-sm font-medium text-neutral-700 dark:text-neutral-300 mb-2">
            Mot de passe <span className="text-red-500">*</span>
          </label>
          <div className="relative">
            <Lock className="absolute left-3 top-1/2 transform -translate-y-1/2 text-neutral-400" size={20} />
            <input
              type={showPassword ? "text" : "password"}
              name="password"
              value={formData.password}
              onChange={handleChange}
              placeholder="Créez un mot de passe sécurisé"
              className={`
                w-full pl-11 pr-12 py-3.5 rounded-lg border
                ${errors.password 
                  ? 'border-red-300 dark:border-red-700 bg-red-50 dark:bg-red-900/20' 
                  : 'border-neutral-300 dark:border-neutral-700 bg-white dark:bg-neutral-800'
                }
                text-neutral-900 dark:text-white
                placeholder-neutral-500 dark:placeholder-neutral-400
                focus:outline-none focus:ring-2 focus:ring-primary-500/50
                transition-all duration-200
              `}
            />
            <button
              type="button"
              onClick={() => setShowPassword(!showPassword)}
              className="absolute right-3 top-1/2 transform -translate-y-1/2 text-neutral-500 hover:text-neutral-700 dark:hover:text-neutral-300"
            >
              {showPassword ? <EyeOff size={20} /> : <Eye size={20} />}
            </button>
          </div>
          {errors.password && (
            <p className="mt-2 text-sm text-red-600 dark:text-red-400">
              {errors.password}
            </p>
          )}

          {/* Password strength */}
          {formData.password && (
            <div className="mt-2">
              <div className="flex justify-between items-center mb-1">
                <span className="text-xs text-neutral-600 dark:text-neutral-400">
                  Force du mot de passe:
                </span>
                <span className={`text-xs font-semibold px-2 py-1 rounded-full ${passwordStrength.color} text-white`}>
                  {passwordStrength.label}
                </span>
              </div>
              <div className="h-1.5 w-full bg-neutral-200 dark:bg-neutral-700 rounded-full overflow-hidden">
                <div 
                  className={`h-full ${passwordStrength.color} transition-all duration-300`}
                  style={{ width: `${((passwordStrength.score + 1) / 5) * 100}%` }}
                />
              </div>
            </div>
          )}
        </div>

        {/* Confirm Password */}
        <div>
          <label className="block text-sm font-medium text-neutral-700 dark:text-neutral-300 mb-2">
            Confirmer le mot de passe <span className="text-red-500">*</span>
          </label>
          <div className="relative">
            <Lock className="absolute left-3 top-1/2 transform -translate-y-1/2 text-neutral-400" size={20} />
            <input
              type={showConfirmPassword ? "text" : "password"}
              name="confirmPassword"
              value={formData.confirmPassword}
              onChange={handleChange}
              placeholder="Retapez votre mot de passe"
              className={`
                w-full pl-11 pr-12 py-3.5 rounded-lg border
                ${errors.confirmPassword 
                  ? 'border-red-300 dark:border-red-700 bg-red-50 dark:bg-red-900/20' 
                  : 'border-neutral-300 dark:border-neutral-700 bg-white dark:bg-neutral-800'
                }
                text-neutral-900 dark:text-white
                placeholder-neutral-500 dark:placeholder-neutral-400
                focus:outline-none focus:ring-2 focus:ring-primary-500/50
                transition-all duration-200
              `}
            />
            <button
              type="button"
              onClick={() => setShowConfirmPassword(!showConfirmPassword)}
              className="absolute right-3 top-1/2 transform -translate-y-1/2 text-neutral-500 hover:text-neutral-700 dark:hover:text-neutral-300"
            >
              {showConfirmPassword ? <EyeOff size={20} /> : <Eye size={20} />}
            </button>
          </div>
          {errors.confirmPassword && (
            <p className="mt-2 text-sm text-red-600 dark:text-red-400">
              {errors.confirmPassword}
            </p>
          )}
        </div>

        {/* Terms checkbox */}
        <div>
          <label className="flex items-start space-x-3">
            <div className="relative flex-shrink-0">
              <input
                type="checkbox"
                name="acceptTerms"
                checked={formData.acceptTerms}
                onChange={handleChange}
                className="absolute opacity-0 w-0 h-0"
                id="acceptTerms"
              />
              <div className={`
                w-5 h-5 rounded border flex items-center justify-center
                ${formData.acceptTerms 
                  ? 'bg-primary-600 border-primary-600' 
                  : 'border-neutral-300 dark:border-neutral-700'
                }
                transition-colors duration-200
              `}>
                {formData.acceptTerms && (
                  <CheckCircle size={14} className="text-white" />
                )}
              </div>
            </div>
            <div className="text-sm">
              <span className="text-neutral-700 dark:text-neutral-300">
                J'accepte les conditions d'utilisation et la politique de confidentialité
              </span>
              {errors.acceptTerms && (
                <p className="text-red-600 dark:text-red-400 text-sm mt-1">
                  {errors.acceptTerms}
                </p>
              )}
            </div>
          </label>
        </div>

        {/* Submit button */}
        <button
          type="submit"
          disabled={isSubmitting}
          className={`
            w-full py-3.5 px-4 rounded-lg font-semibold
            ${isSubmitting 
              ? 'bg-primary-400 cursor-not-allowed' 
              : 'bg-primary-600 hover:bg-primary-700'
            }
            text-white
            focus:outline-none focus:ring-2 focus:ring-primary-500 focus:ring-offset-2
            transition-all duration-200
            transform hover:scale-[1.02] active:scale-[0.98]
            shadow-lg hover:shadow-xl
          `}
        >
          {isSubmitting ? (
            <div className="flex items-center justify-center">
              <div className="animate-spin rounded-full h-5 w-5 border-b-2 border-white mr-2"></div>
              Création du compte...
            </div>
          ) : (
            "Créer mon compte"
          )}
        </button>
      </form>
    </AuthLayout>
  );
};

export default Register;
